package com.jobpilot.application;import com.jobpilot.config.CurrentUserService;import com.jobpilot.job.JobService;import org.springframework.stereotype.Service;import org.springframework.web.server.ResponseStatusException;import java.util.*;import static org.springframework.http.HttpStatus.NOT_FOUND;
@Service public class ApplicationService{private final ApplicationRepository repo;private final JobService jobs;private final CurrentUserService current;public ApplicationService(ApplicationRepository r,JobService j,CurrentUserService c){repo=r;jobs=j;current=c;}public List<ApplicationDtos.View>list(){return repo.findByUserIdOrderByUpdatedAtDesc(current.get().getId()).stream().map(ApplicationDtos::view).toList();}public ApplicationDtos.View create(ApplicationDtos.CreateApplication d){var a=new JobApplication();a.setUser(current.get());a.setJob(jobs.owned(d.jobId()));a.setNotes(d.notes());return ApplicationDtos.view(repo.save(a));}public ApplicationDtos.View update(Long id,ApplicationDtos.UpdateApplication d){var a=repo.findByIdAndUserId(id,current.get().getId()).orElseThrow(()->new ResponseStatusException(NOT_FOUND,"Application not found"));a.setStatus(d.status());a.setNotes(d.notes());return ApplicationDtos.view(repo.save(a));}public void delete(Long id){var a=repo.findByIdAndUserId(id,current.get().getId()).orElseThrow();repo.delete(a);}}
